 *
 * - When `exact` is true, `currentRoute` must match the full `path` pattern
 *   (dynamic segments such as `:id` are supported via `path-to-regexp`).
 * - When `exact` is false/omitted, `currentRoute` matches if it is the `path`
 *   itself or any sub-path at a segment boundary (e.g. `/dashboard/settings`
 *   matches `/dashboard`, but `/dashboard-extra` does not). The root path `/`
 *   only matches itself.
 *
 * Matching is case-insensitive unless `sensitive` is true. Trailing slash
 * mismatches are tolerated unless `strict` is true.
 */
export const isPathMatchingRoute = ({
  currentRoute,
  exact,
  path: viewPath,
  sensitive,
  strict,
}: {
  currentRoute: string
  exact?: boolean
  path?: string
  sensitive?: boolean
  strict?: boolean
}): boolean => {
  // if no path is defined, we cannot match it so return false early
  if (!viewPath) {
    return false
  }

  if (exact) {
    // run the view path through `pathToRegexp` to resolve any dynamic segments
    // i.e. `/admin/custom-view/:id` -> `/admin/custom-view/123`
    const keys = []
    const regex = pathToRegexp(viewPath, keys, {
      sensitive,
      strict,
    })

    return regex.test(currentRoute)
  }

  let route = currentRoute
  let path = viewPath

  if (!sensitive) {
    route = route.toLowerCase()
    path = path.toLowerCase()
  }

  const routeHasTrailingSlash = route.length > 1 && route.endsWith('/')
  const pathHasTrailingSlash = path.length > 1 && path.endsWith('/')

  if (strict) {
    // a trailing slash difference must result in no match
    if (routeHasTrailingSlash !== pathHasTrailingSlash) {
      return false
    }
  } else {
    // tolerate trailing slash mismatches by normalizing both sides
    // (never reduce the root `/` to an empty string)
    if (routeHasTrailingSlash) {
      route = route.slice(0, -1)
    }
    if (pathHasTrailingSlash) {
      path = path.slice(0, -1)
    }
  }

  if (!route.startsWith(path)) {
    return false
  }

  // the match must occur at a segment boundary — the remaining portion of the
  // route must be empty or begin with `/`. This also ensures the root path `/`
  // only matches itself (e.g. `/login` leaves `login`, which is not a boundary).
  const remaining = route.slice(path.length)

  return remaining === '' || remaining.startsWith('/')
}
