[metadata] {"type": "create", "filePath": "/workspace/repo/packages/next/src/views/Root/getCustomCollectionViewByRoute.ts", "content": "import type {
  AdminViewServerProps,
  PayloadComponent,
  SanitizedCollectionConfig,
} from 'payload'

import { isPathMatchingRoute } from './isPathMatchingRoute.js'

/**
 * Built-in collection view keys that are handled by dedicated routes and must
 * never be treated as custom, path-based views.
 */
const builtInViewKeys = ['edit', 'list']

/**
 * Finds the matching custom collection view for the current URL.
 *
 * The `adminRoute` prefix is stripped from `currentRoute` before matching
 * (when `adminRoute` is `/`, no stripping is needed). Built-in view keys
 * (`edit`, `list`) are skipped, as are any views missing a `path` (string) or
 * `Component`. The first view whose `baseRoute + path` matches is returned.
 */
export const getCustomCollectionViewByRoute = ({
  adminRoute,
  baseRoute,
  currentRoute: currentRouteWithAdmin,
  views,
}: {
  adminRoute: string
  baseRoute: string
  currentRoute: string
  views: SanitizedCollectionConfig['admin']['components']['views'] | undefined
}): {
  view: { payloadComponent?: PayloadComponent<AdminViewServerProps> }
  viewKey: null | string
} => {
  if (!views || typeof views !== 'object') {
    return {
      view: {},
      viewKey: null,
    }
  }

  const currentRoute =
    adminRoute === '/' ? currentRouteWithAdmin : currentRouteWithAdmin.replace(adminRoute, '')

  for (const [viewKey, view] of Object.entries(views)) {
    if (builtInViewKeys.includes(viewKey)) {
      continue
    }

    const customView = view as {
      Component?: PayloadComponent<AdminViewServerProps>
      exact?: boolean
      path?: string
      sensitive?: boolean
      strict?: boolean
    }

    if (!customView || typeof customView.path !== 'string' || !customView.Component) {
      continue
    }

    const isMatching = isPathMatchingRoute({
      currentRoute,
      exact: customView.exact,
      path: `${baseRoute}${customView.path}`,
      sensitive: customView.sensitive,
      strict: customView.strict,
    })

    if (isMatching) {
      return {
        view: {
          payloadComponent: customView.Component,
        },
        viewKey,
      }
    }
  }

  return {
    view: {},
    viewKey: null,
  }
}
