const builtInCollectionViewKeys = ['edit', 'list']

/**
 * Validates custom collection views at startup, warning about entries that are
 * missing a required `path` or `Component`. Such views can never be matched to
 * a route, so surfacing the misconfiguration early prevents silent failures.
 */
export const warnOnInvalidCustomViews = (collection: CollectionConfig): void => {
  const views = collection.admin?.components?.views

  if (!views) {
    return
  }

  for (const [viewKey, view] of Object.entries(views)) {
    if (builtInCollectionViewKeys.includes(viewKey)) {
      continue
